package suite

import "base:intrinsics"
import "core:bufio"
import "core:strings"

Calc_Op :: enum u8 {
	Add,
	Sub,
	Mul,
	Div,
	Mod,
	Neg,    // unary minus
	Lparen, // stack marker only; never applied
}

// Binding power; higher binds tighter. All binary operators are left-associative.
op_precedence := [Calc_Op]u8 {
	.Add    = 1,
	.Sub    = 1,
	.Mul    = 2,
	.Div    = 2,
	.Mod    = 2,
	.Neg    = 3,
	.Lparen = 0,
}

Calc_Error :: enum u8 {
	None,
	Syntax,
	Div_By_Zero,
	Overflow,
}

// Reusable evaluation stacks, kept across lines to avoid per-line allocation.
Calc_State :: struct {
	values: [dynamic]i64,
	ops:    [dynamic]Calc_Op,
}

// Evaluates each line of `input` as an expression and prints its value or
// `error`. Blank lines (only spaces/tabs) print nothing.
calc :: proc(input: []byte, out: ^bufio.Writer) {
	state: Calc_State
	defer {
		delete(state.values)
		delete(state.ops)
	}

	text := string(input)
	for line in strings.split_lines_iterator(&text) {
		if is_blank(line) {
			continue
		}
		if value, err := calc_eval(&state, line); err == .None {
			write_int(out, value)
			bufio.writer_write_byte(out, '\n')
		} else {
			write_line(out, "error")
		}
	}
}

@(private = "file")
is_blank :: proc(s: string) -> bool {
	for c in transmute([]byte)s {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Evaluates one expression with an operator-precedence (shunting-yard) parser.
// Explicit stacks keep arbitrarily deep nesting off the call stack.
calc_eval :: proc(st: ^Calc_State, s: string) -> (result: i64, err: Calc_Error) {
	clear(&st.values)
	clear(&st.ops)

	expect_operand := true
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t':
			i += 1
			continue
		case expect_operand:
			switch c {
			case '0' ..= '9':
				v: i64
				for i < len(s) && s[i] >= '0' && s[i] <= '9' {
					m, o1 := intrinsics.overflow_mul(v, 10)
					a, o2 := intrinsics.overflow_add(m, i64(s[i] - '0'))
					if o1 || o2 {
						return 0, .Overflow
					}
					v = a
					i += 1
				}
				append(&st.values, v)
				expect_operand = false
				continue
			case '-':
				append(&st.ops, Calc_Op.Neg)
			case '(':
				append(&st.ops, Calc_Op.Lparen)
			case:
				return 0, .Syntax
			}
		case:
			op: Calc_Op
			switch c {
			case '+': op = .Add
			case '-': op = .Sub
			case '*': op = .Mul
			case '/': op = .Div
			case '%': op = .Mod
			case ')':
				for {
					top, ok := pop_safe(&st.ops)
					if !ok {
						return 0, .Syntax
					}
					if top == .Lparen {
						break
					}
					apply(st, top) or_return
				}
				i += 1
				continue
			case:
				return 0, .Syntax
			}
			for len(st.ops) > 0 && op_precedence[st.ops[len(st.ops) - 1]] >= op_precedence[op] {
				apply(st, pop(&st.ops)) or_return
			}
			append(&st.ops, op)
			expect_operand = true
		}
		i += 1
	}

	if expect_operand {
		return 0, .Syntax
	}
	for len(st.ops) > 0 {
		top := pop(&st.ops)
		if top == .Lparen {
			return 0, .Syntax
		}
		apply(st, top) or_return
	}
	assert(len(st.values) == 1)
	return st.values[0], .None
}

// Pops the operands of `op` from the value stack and pushes the result.
// The parser guarantees enough operands are present.
@(private = "file")
apply :: proc(st: ^Calc_State, op: Calc_Op) -> Calc_Error {
	if op == .Neg {
		top := &st.values[len(st.values) - 1]
		if top^ == min(i64) {
			return .Overflow
		}
		top^ = -top^
		return .None
	}

	b := pop(&st.values)
	a := &st.values[len(st.values) - 1]
	r: i64
	overflow: bool
	#partial switch op {
	case .Add:
		r, overflow = intrinsics.overflow_add(a^, b)
	case .Sub:
		r, overflow = intrinsics.overflow_sub(a^, b)
	case .Mul:
		r, overflow = intrinsics.overflow_mul(a^, b)
	case .Div:
		if b == 0 {
			return .Div_By_Zero
		}
		if a^ == min(i64) && b == -1 {
			return .Overflow
		}
		r = a^ / b
	case .Mod:
		if b == 0 {
			return .Div_By_Zero
		}
		// The quotient overflows but the remainder is well defined: 0.
		r = 0 if b == -1 else a^ % b
	case:
		unreachable()
	}
	if overflow {
		return .Overflow
	}
	a^ = r
	return .None
}

package suite

import "core:bufio"
import "core:strconv"
import "core:strings"

NIL_NODE :: -1

// A cache entry. Keys and values are slices of the input buffer, which
// outlives the cache, so no copying is needed.
Lru_Node :: struct {
	key, value: string,
	prev, next: i32,
}

// Fixed-capacity LRU cache: a hash map from key to node index plus an
// intrusive doubly linked list ordered from most (head) to least (tail)
// recently used. Every operation is O(1) expected.
Lru_Cache :: struct {
	capacity: int,
	index:    map[string]i32,
	nodes:    [dynamic]Lru_Node,
	free:     [dynamic]i32,
	head:     i32,
	tail:     i32,
}

lru_init :: proc(c: ^Lru_Cache, capacity: int, allocator := context.allocator) {
	c.capacity = capacity
	c.index = make(map[string]i32, min(capacity, 1 << 16), allocator)
	c.nodes = make([dynamic]Lru_Node, 0, min(capacity, 1 << 16), allocator)
	c.free = make([dynamic]i32, allocator)
	c.head, c.tail = NIL_NODE, NIL_NODE
}

lru_destroy :: proc(c: ^Lru_Cache) {
	delete(c.index)
	delete(c.nodes)
	delete(c.free)
}

lru_size :: proc(c: ^Lru_Cache) -> int {
	return len(c.index)
}

@(private = "file")
unlink :: proc(c: ^Lru_Cache, i: i32) {
	n := &c.nodes[i]
	if n.prev != NIL_NODE {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != NIL_NODE {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = NIL_NODE, NIL_NODE
}

@(private = "file")
push_front :: proc(c: ^Lru_Cache, i: i32) {
	n := &c.nodes[i]
	n.prev, n.next = NIL_NODE, c.head
	if c.head != NIL_NODE {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

@(private = "file")
remove_node :: proc(c: ^Lru_Cache, i: i32) {
	unlink(c, i)
	delete_key(&c.index, c.nodes[i].key)
	append(&c.free, i)
}

lru_get :: proc(c: ^Lru_Cache, key: string) -> (value: string, ok: bool) {
	i := c.index[key] or_return
	if i != c.head {
		unlink(c, i)
		push_front(c, i)
	}
	return c.nodes[i].value, true
}

lru_set :: proc(c: ^Lru_Cache, key, value: string) {
	if i, found := c.index[key]; found {
		c.nodes[i].value = value
		if i != c.head {
			unlink(c, i)
			push_front(c, i)
		}
		return
	}
	// Evicting before inserting is equivalent to evicting after, since the
	// new key would be the most recently used and never the victim.
	if len(c.index) >= c.capacity {
		remove_node(c, c.tail)
	}
	i: i32
	if len(c.free) > 0 {
		i = pop(&c.free)
		c.nodes[i] = Lru_Node{key = key, value = value}
	} else {
		i = i32(len(c.nodes))
		append(&c.nodes, Lru_Node{key = key, value = value})
	}
	push_front(c, i)
	c.index[key] = i
}

lru_del :: proc(c: ^Lru_Cache, key: string) -> bool {
	i := c.index[key] or_return
	remove_node(c, i)
	return true
}

// Runs the command script in `input`: a capacity line followed by
// SET/GET/DEL/SIZE commands, one per line.
lru :: proc(input: []byte, out: ^bufio.Writer) {
	text := string(input)

	first, _ := strings.split_lines_iterator(&text)
	capacity, ok := strconv.parse_int(strings.trim_space(first), 10)
	if !ok || capacity < 1 {
		return
	}

	cache: Lru_Cache
	lru_init(&cache, capacity)
	defer lru_destroy(&cache)

	for line in strings.split_lines_iterator(&text) {
		rest := strings.trim_right(line, "\r")
		cmd := next_token(&rest)
		switch cmd {
		case "SET":
			key := next_token(&rest)
			value := next_token(&rest)
			lru_set(&cache, key, value)
		case "GET":
			if value, hit := lru_get(&cache, next_token(&rest)); hit {
				write_line(out, value)
			} else {
				write_line(out, "NULL")
			}
		case "DEL":
			write_line(out, "1" if lru_del(&cache, next_token(&rest)) else "0")
		case "SIZE":
			write_int(out, i64(lru_size(&cache)))
			bufio.writer_write_byte(out, '\n')
		}
	}
}

// Splits off the next space-separated token.
@(private = "file")
next_token :: proc(s: ^string) -> string {
	tok, _, rest := strings.partition(s^, " ")
	s^ = rest
	return tok
}

// suite: a single binary bundling three independent stdin→stdout tools.
//
//   app wordfreq   top-10 word frequencies
//   app lru        LRU cache simulator
//   app calc       64-bit integer expression evaluator
package suite

import "core:bufio"
import "core:fmt"
import "core:os"
import "core:strconv"

OUTPUT_BUFFER_SIZE :: 64 * 1024
READ_CHUNK_SIZE    :: 1 << 20

main :: proc() {
	if len(os.args) < 2 {
		usage()
		os.exit(2)
	}

	input, err := read_all(os.stdin)
	if err != nil {
		fmt.eprintln("error reading standard input:", err)
		os.exit(1)
	}

	out: bufio.Writer
	bufio.writer_init(&out, os.to_stream(os.stdout), OUTPUT_BUFFER_SIZE)
	defer bufio.writer_destroy(&out)

	switch os.args[1] {
	case "wordfreq":
		wordfreq(input, &out)
	case "lru":
		lru(input, &out)
	case "calc":
		calc(input, &out)
	case:
		usage()
		os.exit(2)
	}

	if ferr := bufio.writer_flush(&out); ferr != nil {
		fmt.eprintln("error writing standard output:", ferr)
		os.exit(1)
	}
}

usage :: proc() {
	fmt.eprintln("usage: app (wordfreq | lru | calc) < input")
}

// Reads a file to EOF in large chunks; works for pipes where the size is unknown.
read_all :: proc(f: ^os.File, allocator := context.allocator) -> (data: []byte, err: os.Error) {
	buf := make([dynamic]byte, 0, READ_CHUNK_SIZE, allocator)
	for {
		if cap(buf) - len(buf) < READ_CHUNK_SIZE {
			reserve(&buf, 2 * cap(buf))
		}
		start := len(buf)
		resize(&buf, cap(buf))
		n, rerr := os.read(f, buf[start:])
		resize(&buf, start + n)
		if rerr == .EOF || rerr == .Broken_Pipe || (rerr == nil && n == 0) {
			return buf[:], nil
		}
		if rerr != nil {
			return buf[:], rerr
		}
	}
}

// Writes a signed integer in decimal.
write_int :: proc(w: ^bufio.Writer, v: i64) {
	digits: [32]byte
	bufio.writer_write_string(w, strconv.write_int(digits[:], v, 10))
}

write_line :: proc(w: ^bufio.Writer, s: string) {
	bufio.writer_write_string(w, s)
	bufio.writer_write_byte(w, '\n')
}

package suite

import "core:bufio"
import "core:slice"

TOP_WORDS :: 10

Word_Count :: struct {
	word:  string,
	count: int,
}

// Prints the TOP_WORDS most frequent words in `input`, folding ASCII letters
// to lowercase. `input` is lowercased in place so that words can be slices of it.
wordfreq :: proc(input: []byte, out: ^bufio.Writer) {
	counts := make(map[string]int, 1 << 14)
	defer delete(counts)

	i, n := 0, len(input)
	for i < n {
		for i < n && !is_ascii_letter(input[i]) {
			i += 1
		}
		start := i
		for i < n && is_ascii_letter(input[i]) {
			input[i] |= 0x20 // ASCII letters: setting bit 5 lowercases
			i += 1
		}
		if i > start {
			counts[string(input[start:i])] += 1
		}
	}

	top := top_words(counts)
	for wc in top {
		write_int(out, i64(wc.count))
		bufio.writer_write_byte(out, ' ')
		write_line(out, wc.word)
	}
}

// Orders by count descending, then word ascending.
word_count_less :: proc(a, b: Word_Count) -> bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// Selects the best TOP_WORDS entries in a single pass with a small sorted buffer.
top_words :: proc(counts: map[string]int) -> []Word_Count {
	@(static) buf: [TOP_WORDS]Word_Count
	n := 0
	for word, count in counts {
		wc := Word_Count{word, count}
		if n == TOP_WORDS && !word_count_less(wc, buf[n - 1]) {
			continue
		}
		j := n if n < TOP_WORDS else n - 1
		for j > 0 && word_count_less(wc, buf[j - 1]) {
			buf[j] = buf[j - 1]
			j -= 1
		}
		buf[j] = wc
		if n < TOP_WORDS {
			n += 1
		}
	}
	assert(slice.is_sorted_by(buf[:n], word_count_less))
	return buf[:n]
}

is_ascii_letter :: #force_inline proc(c: byte) -> bool {
	return (c | 0x20) - 'a' < 26
}
